<div class="page-head"><h1>Import runs</h1><?php require __DIR__ . '/_nav.php'; ?></div>
<form method="get" class="inline-form"><label>Source <select name="source" data-autosubmit><option value="">All</option><?php foreach ($sources as $s): ?><option value="<?= e($s['source']) ?>" <?= $source === $s['source'] ? 'selected' : '' ?>><?= e($s['source']) ?></option><?php endforeach; ?></select></label></form>
<table class="tbl"><thead><tr><th>#</th><th>Source</th><th>Status</th><th>Started</th><th class="r">Rows</th><th class="r">New</th><th class="r">Changed</th><th class="r">Removed</th><th class="r">Errors</th><th class="r">Time</th><th>Note</th></tr></thead><tbody>
